// Home Assistant builds its pipeline's language menu out of exactly this.
func Languages(voices []TtsVoice) []string {
	seen := map[string]bool{}
	var out []string
	for _, v := range voices {
		for _, tag := range v.Languages {
			if !seen[tag] {
				seen[tag] = true
				out = append(out, tag)
			}
		}
	}
	sort.Strings(out)
	return out
